 3	declare(strict_types=1);
 4	
 5	namespace testsuites\Application\Admin\Wizard;
 6	
 7	use Application\Admin\Wizard\WizardPreselection;
 8	use PHPUnit\Framework\TestCase;
 9	
10	final class WizardPreselectionTest extends TestCase
11	{
12	    public function test_setAndGetStepValue(): void
13	    {
14	        $preselection = new WizardPreselection();
15	        $preselection->setStepValue('StepOne', 'color', 'blue');
16	        $preselection->setStepValue('StepOne', 'size', 'large');
17	
18	        $values = $preselection->getStepValues('StepOne');
19	
20	        $this->assertSame('blue', $values['color']);
21	        $this->assertSame('large', $values['size']);
22	        $this->assertSame(array(), $preselection->getStepValues('Nonexistent'));
23	    }
24	
25	    public function test_hasStepValues(): void
26	    {
27	        $preselection = new WizardPreselection();
28	
29	        $this->assertFalse($preselection->hasStepValues('StepOne'));
30	
31	        $preselection->setStepValue('StepOne', 'foo', 'bar');
32	
33	        $this->assertTrue($preselection->hasStepValues('StepOne'));
34	        $this->assertFalse($preselection->hasStepValues('StepTwo'));
35	    }
36	
37	    public function test_toArray(): void
38	    {
39	        $preselection = new WizardPreselection();
40	        $preselection->setStepValue('StepA', 'key1', 'value1');
41	        $preselection->setStepValue('StepB', 'key2', 42);
42	
43	        $expected = array(
44	            'StepA' => array('key1' => 'value1'),
45	            'StepB' => array('key2' => 42),
46	        );
47	
48	        $this->assertSame($expected, $preselection->toArray());
49	    }
50	
51	    public function test_isEmpty(): void
52	    {
53	        $preselection = new WizardPreselection();
54	
55	        $this->assertTrue($preselection->isEmpty());
56	
57	        $preselection->setStepValue('StepOne', 'foo', 'bar');
58	
59	        $this->assertFalse($preselection->isEmpty());
60	    }
61	
62	    public function test_fluentInterface(): void
63	    {
64	        $preselection = new WizardPreselection();
65	
66	        $result = $preselection
67	            ->setStepValue('StepOne', 'a', 1)
68	            ->setStepValue('StepOne', 'b', 2)
69	            ->setStepValue('StepTwo', 'c', 3);
70	
71	        $this->assertSame($preselection, $result);
72	        $this->assertSame(2, $preselection->getStepValues('StepOne')['b']);
73	        $this->assertSame(3, $preselection->getStepValues('StepTwo')['c']);
74	    }
75	
76	    public function test_getStepNames(): void
77	    {
78	        $preselection = new WizardPreselection();
79	
80	        $this->assertSame(array(), $preselection->getStepNames());
81	
82	        $preselection->setStepValue('Alpha', 'x', true);
83	        $preselection->setStepValue('Beta', 'y', false);
84	
85	        $this->assertSame(array('Alpha', 'Beta'), $preselection->getStepNames());
86	    }
87	}

